    'admin_leader_operating_system.leader.opportunity_modal_empty' => 'Obecnie nie ma dodatkowych sygnałów, ale warto skupić się na skuteczniejszych wezwaniach do działania, lepszej konwersji i prostszej ścieżce do rejestracji lub zakupu.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.label' => 'Zwiększ udział kliknięć kierujących do sklepu internetowego lub ofert rabatowych',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.text' => 'Współpracownik ma łącznie %s kliknięć, ale tylko %s%% z nich prowadzi do sklepu internetowego Forever lub stron z rabatami.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_1' => 'Przenieś wezwanie do działania dotyczące sklepu internetowego lub zniżki wyżej na stronie i powtórz je w dolnej części profilu lub wpisu na blogu.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2' => 'Dodaj wyraźniejsze wezwanie do działania na głównej ścieżce ruchu, aby odwiedzający trafiali do miejsca docelowego Forever zamiast wyłącznie do treści informacyjnych.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2_source' => 'W przypadku źródła %s przetestuj wyraźniejsze wezwanie do działania, które przeniesie użytkowników bezpośrednio z treści do sklepu internetowego Forever lub oferty rabatowej.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_3' => 'Sprawdź, czy bloki bloga, sprzedaży i zniżek wystarczająco jasno i często pokazują ścieżkę zakupu.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.label' => 'Zamień kliknięcia w sklepie internetowym na rejestracje lub zakupy',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.text' => 'W tym okresie współpracownik uzyskał już %s kliknięć w sklepie internetowym, ale nadal nie ma rejestracji.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_1' => 'Sprawdź, czy kliknięcie otwiera prawidłowy adres URL polecenia i prowadzi do właściwej strony lub widoku sklepu internetowego bez błędów.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_2' => 'Ulepsz wiadomość przed kliknięciem: wyjaśnij, co otrzyma odwiedzający, dlaczego warto kliknąć teraz i co się stanie po przejściu na stronę Forever.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3' => 'Przetestuj prostszą ścieżkę rejestracji lub zakupu i usuń niejasne kroki następujące po pierwszym kliknięciu.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3_country' => 'Jeśli większość ruchu pochodzi z %s, sprawdź, czy strona docelowa jest prawidłowo zlokalizowana i otwiera właściwą wersję dla danego rynku.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.label' => 'Zwiększaj współczynnik konwersji wraz ze wzrostem ruchu',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.text' => 'Ruch wzrósł o %s%%, ale współczynnik rejestracji wynosi zaledwie %s%%, więc dodatkowe kliknięcia nie przynoszą jeszcze wystarczających rezultatów.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_1' => 'Zachowaj źródło, które napędza wzrost, ale dopracuj tekst wezwania do działania i wiadomość wprowadzającą, aby lepiej weryfikowały zamiar zakupu.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_2' => 'Zbuduj zaufanie przed wezwaniem do działania, dodając opinię, wynik, krótką sekcję FAQ lub jasne wyjaśnienie tego, co stanie się po kliknięciu.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_3' => 'Porównuj źródła kliknięć i skupiaj się na tych kanałach, które przynoszą rejestracje lub lepsze kontakty, a nie tylko duży ruch.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.label' => 'Wykorzystaj istniejące zainteresowanie, aby stworzyć skuteczniejszą ścieżkę sprzedaży',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.text' => 'Aplikacja generuje już sygnały przez WhatsApp (%1$s), produkty (%2$s) i rejestracje (%3$s), ale wciąż nie kieruje wystarczającej liczby osób do sklepu.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_1' => 'Umieść jeden wyraźny główny przycisk prowadzący do sklepu nad pozostałymi opcjami sprzedaży.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_2' => 'Ujednolić przekaz w treściach, WhatsAppie i blokach sprzedażowych, tak aby wszystkie wskazywały ten sam kolejny krok.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_3' => 'Zachowaj bloki, które wzbudzają zainteresowanie, ale wyraźnie wskaż, gdzie należy od razu kliknąć, aby dokonać zakupu lub się zapisać.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.label' => 'Utrzymuj tempo dzięki mniejszym optymalizacjom',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.text' => 'Możliwości rozwoju jest dużo nie z powodu jednego poważnego problemu, lecz drobnych obszarów wymagających poprawy.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_1' => 'Nadal kieruj ruch do najskuteczniejszych miejsc z wezwaniem do działania, które już dobrze się sprawdzają.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_2' => 'Testuj dalej treść nagłówka, kolejność CTA i elementy budujące zaufanie, aby utrzymać lub obniżyć ocenę szansy.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_3' => 'Sprawdzaj, czy dodatkowe kliknięcia przekładają się na rejestracje, a nie tylko na większy ruch.',
